    "category": "Governo",
    "ingestedAt": "28/10/2026 às 11:44",
    "imageUrl": "https://imagens.ebc.com.br/sUGwEN2yeP02B6se3RupYFrXCx4=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2025/01/06/img_9054.jpg?itok=PFTv1yBJ",
