    "category": "Esportes",
    "ingestedAt": "28/10/2026 às 09:12",
    "imageUrl": "https://imagens.ebc.com.br/-PaaJY4KY8aGkVGcGCX0iJd7Rlc=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/10/27/foto-montagem-meio-campista.png?itok=pWhvk9qR",
    "imageCaption": "Prêmio TV Brasil Petrobras Para Elas revela meio-campistas finalistas",
